const imageSources={"comparison.png":"data:image/png;base64,","CrystalGarden-reactive-original.png":"data:image/png;base64,","CrystalGarden-reactive-risograph.png":"data:image/png;base64,","CrystalGarden-reactive-woodcut.png":"data:image/png;base64,","overview-original.png":"data:image/png;base64,","overview-risograph.png":"data:image/png;base64,","overview-woodcut.png":"data:image/png;base64,","pistol-impact-original.png":"data:image/png;base64,","pistol-impact-risograph.png":"data:image/png;base64,","pistol-impact-woodcut.png":"data:image/png;base64,","RoboticForest-reactive-original.png":"data:image/png;base64,","RoboticForest-reactive-risograph.png":"data:image/png;base64,","RoboticForest-reactive-woodcut.png":"data:image/png;base64,"};function imageURL(name){if(!imageSources[name])throw new Error("Imagen no incrustada: "+name);return imageSources[name]}
const scene=document.querySelector('#scene');const styles=[['original','Original archivado'],['risograph','Risograph · Fantasy'],['woodcut','Woodcut · Grabado']];function update(){const key=scene.value;document.querySelector('#cards').innerHTML=styles.map(([id,label])=>`<div class="card"><h3>${label}</h3><a href="${imageURL(key+'-'+id+'.png')}" target="_blank"><img src="${imageURL(key+'-'+id+'.png')}" alt="${label}"></a></div>`).join('');document.querySelector('#under').src=imageURL(key+'-woodcut.png');document.querySelector('#over').src=imageURL(key+'-risograph.png')}scene.onchange=update;document.querySelector('#wipe').oninput=e=>{const n=e.target.value;document.querySelector('#over').style.clipPath=`inset(0 ${100-n}% 0 0)`;document.querySelector('#line').style.left=n+'%'};document.querySelector('#zoom').onclick=e=>{document.body.classList.toggle('full');e.target.textContent=document.body.classList.contains('full')?'Ajustar a la ventana':'Ver a tamaño real'};update();